import { useState, useCallback } from 'react';

function parseSearch<T extends Record<string, string>>(search: string, defaults: T): T {
  const params = new URLSearchParams(search);
  const result = { ...defaults };
  for (const key of Object.keys(defaults)) {
    if (params.has(key)) result[key as keyof T] = params.get(key) as T[keyof T];
  }
  return result;
}

export function useQueryParams<T extends Record<string, string>>(defaults: T): [T, (next: Partial<T>) => void] {
  const [params, setParams] = useState<T>(() => parseSearch(window.location.search, defaults));

  const setter = useCallback((next: Partial<T>) => {
    setParams(prev => {
      const merged = { ...prev, ...next };
      const search = new URLSearchParams(merged as Record<string, string>).toString();
      window.history.replaceState({}, '', `?${search}`);
      return merged;
    });
  }, []);

  return [params, setter];
}
